// CreateTableWithDBType creates the Fixed_Asset table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *FixedAsset) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FixedAssetTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetFixedAssetPostgresTableSchema()
	} else {
		schema = GetFixedAssetTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Fixed_Asset table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *FixedAsset) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FixedAssetTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Fixed_Asset$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (search_description)`,
		fmt.Sprintf("%s$Fixed_Asset$search_description", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index search_description: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_class_code)`,
		fmt.Sprintf("%s$Fixed_Asset$fa_class_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_class_code: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_subclass_code)`,
		fmt.Sprintf("%s$Fixed_Asset$fa_subclass_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_subclass_code: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (component_of_main_asset, main_asset_component)`,
		fmt.Sprintf("%s$Fixed_Asset$component_of_main_asset", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index component_of_main_asset: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_location_code)`,
		fmt.Sprintf("%s$Fixed_Asset$fa_location_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_location_code: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (department_code)`,
		fmt.Sprintf("%s$Fixed_Asset$department_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index department_code: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (project_code)`,
		fmt.Sprintf("%s$Fixed_Asset$project_code", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index project_code: %w", err)
	}
	var keys []sift.Key
	for _, spec := range fixedAssetSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, FixedAssetTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, FixedAssetTableName, keys)
}

// fixedAssetSIFTSpecs are the table's keys with sum_index_fields
func fixedAssetSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *FixedAsset) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, FixedAssetTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range fixedAssetSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, FixedAssetTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: FixedAssetTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, FixedAssetTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

