		var responsible_employeeNull sql.NullString
		var serial_noNull sql.NullString
		var last_date_modifiedNull sql.NullString
		var blockedBool sql.NullBool
		var maintenance_vendor_noNull sql.NullString
		var under_maintenanceBool sql.NullBool
		var next_service_dateNull sql.NullString
		var inactiveBool sql.NullBool
		var no_seriesNull sql.NullString

		err := t.currentRows.Scan(
			&noNull,
			&descriptionNull,
			&search_descriptionNull,
			&description_2Null,
			&fa_class_codeNull,
			&fa_subclass_codeNull,
			&department_codeNull,
			&project_codeNull,
			&location_codeNull,
			&fa_location_codeNull,
			&vendor_noNull,
			&main_asset_componentInt,
			&component_of_main_assetNull,
			&budgeted_assetBool,
			&warranty_dateNull,
			&responsible_employeeNull,
			&serial_noNull,
			&last_date_modifiedNull,
			&blockedBool,
			&t.Picture,
			&maintenance_vendor_noNull,
			&under_maintenanceBool,
			&next_service_dateNull,
			&inactiveBool,
			&no_seriesNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Fixed_Asset record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.No = types.NewCode(noNull.String)
